'use client';
import { FormEvent,useCallback,useEffect,useMemo,useState } from 'react';
type Vendor={id:string;name:string;category:string;preferred:number;contact_name:string;email:string;phone:string;website:string;address:string;notes:string};type Job={id:string;name:string;project_type_key:string;project_type_category:string;smart_defaults_json:string};type Workflow={id:string;project_id:string;project_name:string;template_key:string};type Closeout={id:string;project_id:string;project_name:string;status:string};type Assignment={id:string;vendor_id:string;vendor_name:string;category:string;project_id?:string;workflow_instance_id?:string;closeout_task_group_id?:string;assignment_role?:string;reference_note?:string};type Payload={vendors:Vendor[];jobs:Job[];workflows:Workflow[];closeouts:Closeout[];jobAssignments:Assignment[];workflowAssignments:Assignment[];closeoutReferences:Assignment[];categories:string[]};
export default function VendorManager({workspaceName,initialProjectId,module}:{workspaceName:string;initialProjectId:string;module:{purpose:string;roles:readonly string[];artifacts:readonly string[];limitations:readonly string[];publishingNotes:readonly string[]}}){const [data,setData]=useState<Payload|null>(null),[editing,setEditing]=useState<Vendor|null>(null),[query,setQuery]=useState(''),[targetType,setTargetType]=useState<'job'|'workflow'|'closeout'>('job'),[targetId,setTargetId]=useState(initialProjectId),[busy,setBusy]=useState(true),[error,setError]=useState(''),[notice,setNotice]=useState('');const load=useCallback(async()=>{const response=await fetch('/api/command/vendors',{cache:'no-store'}),payload=await response.json() as Payload&{error?:string};if(!response.ok)throw new Error(payload.error||'Vendor Manager could not load.');setData(payload);setTargetId(current=>current||(initialProjectId&&payload.jobs.some(job=>job.id===initialProjectId)?initialProjectId:payload.jobs[0]?.id||''));setBusy(false)},[initialProjectId]);useEffect(()=>{let active=true;const timer=window.setTimeout(()=>load().catch(reason=>{if(active){setError(reason instanceof Error?reason.message:'Vendor Manager could not load.');setBusy(false)}}),0);return()=>{active=false;window.clearTimeout(timer)}},[load]);
  async function send(body:Record<string,unknown>){setBusy(true);setError('');setNotice('');try{const response=await fetch('/api/command/vendors',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)}),payload=await response.json() as{error?:string};if(!response.ok)throw new Error(payload.error||'Vendor Manager could not save the change.');await load();return true}catch(reason){setError(reason instanceof Error?reason.message:'Vendor Manager could not save the change.');setBusy(false);return false}}
  async function save(event:FormEvent<HTMLFormElement>){event.preventDefault();const form=event.currentTarget,values=Object.fromEntries(new FormData(form));if(await send({action:editing?'update':'create',id:editing?.id,...values,preferred:values.preferred==='on'})){setEditing(null);form.reset();setNotice(editing?'Vendor updated.':'Vendor added to this company workspace.')}}
  async function remove(vendor:Vendor){if(!window.confirm(`Remove ${vendor.name} and its internal assignments?`))return;if(await send({action:'delete',id:vendor.id})){setEditing(null);setNotice('Vendor removed from this company workspace.')}}
  const targets=targetType==='job'?data?.jobs||[]:targetType==='workflow'?data?.workflows||[]:data?.closeouts||[];const targetAssignments=targetType==='job'?data?.jobAssignments||[]:targetType==='workflow'?data?.workflowAssignments||[]:data?.closeoutReferences||[];const activeAssignments=targetAssignments.filter(item=>(targetType==='job'?item.project_id:targetType==='workflow'?item.workflow_instance_id:item.closeout_task_group_id)===targetId);const job=targetType==='job'?data?.jobs.find(item=>item.id===targetId):null;const recommended=useMemo(()=>{try{const snapshot=job?.smart_defaults_json?JSON.parse(job.smart_defaults_json) as {vendorCategories?:Array<{label:string}>}:null;return snapshot?.vendorCategories?.map(item=>item.label)||[]}catch{return []}},[job]);const visible=(data?.vendors||[]).filter(vendor=>`${vendor.name} ${vendor.category} ${vendor.contact_name}`.toLowerCase().includes(query.toLowerCase()));
  return <div className="vendor-body"><section className="vendor-heading"><div><small>MODULE R · COMPANY VENDOR DIRECTORY</small><h1>Vendors tied to<br/><em>the work.</em></h1><p>{module.purpose}</p></div><aside><b>{workspaceName}</b><span>{data?.vendors.length||0} private vendor records</span><strong>No global or preloaded vendors.</strong></aside></section>{error&&<p className="command-error" role="alert">{error}</p>}{notice&&<p className="command-success" role="status">✓ {notice}</p>}<section className="vendor-workspace"><form key={editing?.id||'new'} className="vendor-form" onSubmit={save}><div><small>{editing?'EDIT VENDOR':'ADD VENDOR'}</small><h2>{editing?editing.name:'New company vendor'}</h2></div><label>Vendor name<input name="name" required defaultValue={editing?.name||''}/></label><label>Category<select name="category" required defaultValue={editing?.category||'General'}>{(data?.categories||[]).map(item=><option key={item}>{item}</option>)}</select></label><label>Contact name<input name="contactName" defaultValue={editing?.contact_name||''}/></label><label>Email<input name="email" type="email" defaultValue={editing?.email||''}/></label><label>Phone<input name="phone" type="tel" defaultValue={editing?.phone||''}/></label><label>Website<input name="website" type="url" defaultValue={editing?.website||''}/></label><label className="wide">Address<input name="address" defaultValue={editing?.address||''}/></label><label className="wide">Notes<textarea name="notes" rows={3} defaultValue={editing?.notes||''}/></label><label className="preferred"><input name="preferred" type="checkbox" defaultChecked={Boolean(editing?.preferred)}/> Preferred vendor</label><div className="vendor-form-actions"><button disabled={busy}>{editing?'Save vendor':'Add vendor'} →</button>{editing&&<button type="button" onClick={()=>setEditing(null)}>Cancel</button>}</div></form><section className="vendor-directory"><header><div><small>PRIVATE DIRECTORY</small><h2>{data?.vendors.length||0} vendors</h2></div><label>Search<input value={query} onChange={event=>setQuery(event.target.value)} placeholder="Name, category, contact"/></label></header>{busy&&!data?<p>Loading vendors…</p>:!visible.length?<div className="command-empty"><h3>No vendors added.</h3><p>Vendor records begin empty for every company. Add only the businesses your team uses.</p></div>:<div className="vendor-list">{visible.map(vendor=><article key={vendor.id}><div><small>{vendor.category}{vendor.preferred?' · PREFERRED':''}</small><h3>{vendor.name}</h3><p>{vendor.contact_name||'Contact not added'}</p>{vendor.email&&<a href={`mailto:${vendor.email}`}>{vendor.email}</a>}{vendor.phone&&<a href={`tel:${vendor.phone}`}>{vendor.phone}</a>}</div><div><button onClick={()=>setEditing(vendor)}>Edit</button><button onClick={()=>remove(vendor)}>Delete</button></div></article>)}</div>}</section></section><section className="vendor-assign"><header><div><small>OPTIONAL JOB-LINKED REFERENCE</small><h2>Assign vendors</h2><p>Assignments organize the record. They do not contact, hire, or pay a vendor.</p></div><div className="vendor-target-tabs"><button data-active={targetType==='job'} onClick={()=>{setTargetType('job');setTargetId(data?.jobs[0]?.id||'')}}>Job</button><button data-active={targetType==='workflow'} onClick={()=>{setTargetType('workflow');setTargetId(data?.workflows[0]?.id||'')}}>Workflow</button><button data-active={targetType==='closeout'} onClick={()=>{setTargetType('closeout');setTargetId(data?.closeouts[0]?.id||'')}}>Closeout</button></div></header><div className="assignment-controls"><label>{targetType==='job'?'Job':targetType==='workflow'?'Workflow playbook':'Closeout packet'}<select value={targetId} onChange={event=>setTargetId(event.target.value)}><option value="">Choose a record</option>{targets.map(item=><option key={item.id} value={item.id}>{'name'in item?item.name:item.project_name}{'template_key'in item?` · ${item.template_key.replaceAll('-',' ')}`:''}</option>)}</select></label><label>Vendor<select id="vendor-assignment-choice" defaultValue=""><option value="">Choose a vendor</option>{(data?.vendors||[]).map(item=><option key={item.id} value={item.id}>{item.name} · {item.category}</option>)}</select></label><label>Role / reference note<input id="vendor-assignment-note" placeholder="Supplier, trade partner, warranty contact…"/></label><button disabled={busy||!targetId||!data?.vendors.length} onClick={()=>{const vendorId=(document.querySelector('#vendor-assignment-choice') as HTMLSelectElement)?.value,note=(document.querySelector('#vendor-assignment-note') as HTMLInputElement)?.value;if(vendorId)void send({action:'assign',targetType,targetId,vendorId,note}).then(ok=>ok&&setNotice('Vendor assigned to the selected record.'))}}>Assign vendor →</button></div>{targetType==='job'&&targetId&&<div className="smart-vendor-suggestions"><small>MODULE Q · RECOMMENDED CATEGORIES</small>{recommended.length?recommended.map(item=><span key={item}>{item}</span>):<p>Classify the job and refresh Smart Defaults to see category recommendations.</p>}</div>}<div className="assigned-vendors">{activeAssignments.length?activeAssignments.map(item=><article key={item.id}><div><b>{item.vendor_name}</b><span>{item.category} · {item.assignment_role||item.reference_note||'Reference'}</span></div><button onClick={()=>void send({action:'unassign',targetType,targetId,vendorId:item.vendor_id})}>Remove assignment</button></article>):<p>No vendors assigned to this record.</p>}</div></section><section className="automation-reference"><article><small>ROLES</small><h2>Who uses it</h2><ul>{module.roles.map(item=><li key={item}>{item}</li>)}</ul></article><article><small>ARTIFACTS</small><h2>What is stored</h2><ul>{module.artifacts.map(item=><li key={item}>{item}</li>)}</ul></article><article className="publishing-note"><small>HONEST LIMITS</small><h2>What it does not do</h2><ul>{module.limitations.map(item=><li key={item}>{item}</li>)}</ul>{module.publishingNotes.map(item=><p key={item}>{item}</p>)}</article></section></div>}
